from dataclasses import dataclass

@dataclass
class PlaintextPayload:
    data: str

@dataclass
class CiphertextPayload:
    data: bytes
    key_id: str

import os
from google.cloud import kms_v1

class KmsClient:
    def __init__(self):
        self.project_id = os.environ.get("GOOGLE_CLOUD_PROJECT")
        self.location_id = os.environ.get("GOOGLE_CLOUD_KMS_LOCATION")
        self.key_ring_id = os.environ.get("GOOGLE_CLOUD_KMS_KEY_RING")
        self.client = kms_v1.KeyManagementServiceClient()

    def get_key_path(self, key_id: str) -> str:
        return self.client.crypto_key_path(
            self.project_id, self.location_id, self.key_ring_id, key_id
        )

import os
from google.cloud import dlp_v2
from security_models import PlaintextPayload

def check_payload_safety(payload: PlaintextPayload, project_id: str) -> dict:
    dlp_client = dlp_v2.DlpServiceClient()
    project_path = f"projects/{project_id}"

    # Configure the inspect request to look for common sensitive info types
    inspect_config = {
        "info_types": [
            {"name": "EMAIL_ADDRESS"},
            {"name": "PHONE_NUMBER"},
            {"name": "CREDIT_CARD_NUMBER"},
            {"name": "US_SOCIAL_SECURITY_NUMBER"},
        ],
        "min_likelihood": dlp_v2.Likelihood.POSSIBLE,
        "limits": {"max_findings_per_request": 0},
    }

    item = {"value": payload.data}

    response = dlp_client.inspect_content(request={
        "parent": project_path,
        "inspect_config": inspect_config,
        "item": item,
    })

    findings = []
    if response.result.findings:
        for finding in response.result.findings:
            findings.append({
                "info_type": finding.info_type.name,
                "likelihood": dlp_v2.Likelihood(finding.likelihood).name,
                "quote": finding.quote,
            })
    return {"findings": findings, "full_response": str(response)}

import os
from google.cloud import translate

def translate_note(text: str, project_id: str, target_language: str = "en") -> dict:
    client = translate.TranslationServiceClient()
    location = "global"
    parent = f"projects/{project_id}/locations/{location}"

    response = client.translate_text(
        request={
            "parent": parent,
            "contents": [text],
            "target_language_code": target_language,
        }
    )

    translations = []
    for translation in response.translations:
        translations.append({"translated_text": translation.translated_text, "detected_language_code": translation.detected_language_code})

    return {"translations": translations, "full_response": str(response)}
